module Top;
    typedef enum logic [3:0] {LOW = 4'd1, HIGH = 4'd9} Level;
    class Animal;
    endclass
    class Dog extends Animal;
    endclass
    class Rock;
    endclass
    class Holder;
        Level level = LOW;
        Dog dogs[int];
    endclass
    class Maker;
        int made;
        Holder holder;
        function Holder get();
            made++;
            if (holder == null)
                holder = new;
            return holder;
        endfunction
    endclass
    typedef struct packed {
        Level level;
        logic [3:0] pad;
    } Entry;
    Entry items[4];
    int picked;
    function automatic int pick();
        picked++;
        return picked;
    endfunction
    Maker m;
    Animal animal;
    Rock rock;
    initial begin
        m = new;
        $display("%0d %0d", $cast(m.get.level, 2), m.made);
        $display("%0d %0d %s", $cast(m.get.level, 9), m.made, m.holder.level.name());
        animal = Dog::new;
        $display("%0d %0d %0d", $cast(m.get.dogs[pick()], animal), m.made, picked);
        $display("%0d %0d", m.holder.dogs.exists(1), m.holder.dogs.num());
        $display("%0d %0d", $cast(m.get.dogs[pick()], rock), picked);
        $display("%0d", m.holder.dogs.num());
        picked = 0;
        $display("%0d %0d %s", $cast(items[pick()].level, 9), picked, items[1].level.name());
        $display("%0d %0d %s", $cast(items[pick()].level, 3), picked, items[2].level.name());
    end
endmodule
module Wrapped;
 Top dut();
endmodule
